package com.leetcode.backend.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="contests", indexes={@Index(name="idx_contest_schedule",columnList="start_at,end_at"),@Index(name="idx_contest_slug",columnList="slug")}) public class Contest {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=160) private String title; @Column(nullable=false,unique=true,length=180) private String slug; @Column(columnDefinition="TEXT") private String description; @Column(columnDefinition="TEXT") private String rulesText; @Column(name="accent",length=30) private String accent;
 @Column(name="start_at",nullable=false) private LocalDateTime startAt; @Column(name="end_at",nullable=false) private LocalDateTime endAt; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ContestStatus status=ContestStatus.DRAFT; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ContestVisibility visibility=ContestVisibility.PUBLIC; @Column(name="access_code_hash") private String accessCodeHash; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt;
 @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} public ContestStatus derivedStatus(){if(status==ContestStatus.CANCELLED||status==ContestStatus.DRAFT)return status;LocalDateTime now=LocalDateTime.now();return now.isBefore(startAt)?ContestStatus.UPCOMING:now.isBefore(endAt)?ContestStatus.LIVE:ContestStatus.ENDED;}
 public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getSlug(){return slug;} public void setSlug(String v){slug=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getRulesText(){return rulesText;} public void setRulesText(String v){rulesText=v;} public String getAccent(){return accent;} public void setAccent(String v){accent=v;} public LocalDateTime getStartAt(){return startAt;} public void setStartAt(LocalDateTime v){startAt=v;} public LocalDateTime getEndAt(){return endAt;} public void setEndAt(LocalDateTime v){endAt=v;} public ContestStatus getStatus(){return status;} public void setStatus(ContestStatus v){status=v;} public ContestVisibility getVisibility(){return visibility;} public void setVisibility(ContestVisibility v){visibility=v;} public String getAccessCodeHash(){return accessCodeHash;} public void setAccessCodeHash(String v){accessCodeHash=v;} public User getCreatedBy(){return createdBy;} public void setCreatedBy(User v){createdBy=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;}
}
